// Dijkstra: shortest path cost between two nodes
const edges=[["a", "b", 1], ["b", "c", 2], ["a", "c", 4]];
const nodes={};edges.forEach(e=>{nodes[e[0]]=1;nodes[e[1]]=1;});
const dist={},Q=new Set(Object.keys(nodes));
Object.keys(nodes).forEach(n=>dist[n]=1e9);dist["a"]=0;
while(Q.size){let u=null;Q.forEach(n=>{if(u===null||dist[n]<dist[u])u=n;});Q.delete(u);
for(const [a,b,w] of edges){if(a===u&&Q.has(b)&&dist[u]+w<dist[b])dist[b]=dist[u]+w;if(b===u&&Q.has(a)&&dist[u]+w<dist[a])dist[a]=dist[u]+w;}}
console.log('shortest '+"a"+' -> '+"c"+' = '+dist["c"]);

